import math

def find_order(base, modulus):
    if math.gcd(base, modulus) != 1:
        return None

    phi = modulus - modulus // 2 if modulus > 2 else 1 # Simplified for prime power 5^4
    # More accurately, phi(5^4) = 5^4 - 5^3 = 625 - 125 = 500
    phi_modulus = 500 

    # Check divisors of 500: 1, 2, 4, 5, 10, 20, 25, 50, 100, 125, 250, 500
    divisors = []
    for i in range(1, int(math.sqrt(phi_modulus)) + 1):
        if phi_modulus % i == 0:
            divisors.append(i)
            if i * i != phi_modulus:
                divisors.append(phi_modulus // i)
    divisors.sort()

    for d in divisors:
        if pow(base, d, modulus) == 1:
            return d
    return phi_modulus # Should not happen if phi was calculated correctly

k_625 = find_order(3, 625)
print(f"Order mod 625: {k_625}")

